# Thinkific Integration
import requests

THINKIFIC_API_KEY = "09586040978jtrijgkj5fdjnjlsewjnrej85u49u594u95u4nrej0jrjtnjgnnf"
THINKIFIC_SUBDOMAIN = "your-subdomain"

def get_thinkific_courses():
    """Get all courses"""
    response = requests.get(
        f"https://api.thinkific.com/api/public/v1/courses",
        headers={
            "X-Auth-API-Key": THINKIFIC_API_KEY,
            "X-Auth-Subdomain": THINKIFIC_SUBDOMAIN
        }
    )
    return response.json()

def create_enrollment(user_id, course_id):
    """Enroll user in course"""
    response = requests.post(
        f"https://api.thinkific.com/api/public/v1/enrollments",
        headers={
            "X-Auth-API-Key": THINKIFIC_API_KEY,
            "X-Auth-Subdomain": THINKIFIC_SUBDOMAIN
        },
        json={
            "user_id": user_id,
            "course_id": course_id
        }
    )
    return response.json()
